5	import { Label } from "@repo/design-system/components/ui/label";
6	import { toast } from "@repo/design-system/components/ui/sonner";
7	import { useCallback, useState } from "react";
8	
9	interface SignUpSuccess {
10	  message: string;
11	}
12	
13	interface SignUpError {
14	  error: {
15	    message: string;
16	    name: string;
17	  };
18	}
19	
20	type SignUpResponse = SignUpSuccess | SignUpError;
21	
22	export function Digest() {
23	  const [status, setStatus] = useState<"idle" | "loading">("idle");
24	
25	  const handleSignUp = useCallback(
26	    async (event: React.SyntheticEvent<HTMLFormElement>) => {
27	      event.preventDefault();
28	      const form = event.currentTarget;
29	      const emailInput = form.elements.namedItem("email") as HTMLInputElement;
30	      setStatus("loading");
31	
32	      try {
33	        const res = await fetch("/api/confirm", {
34	          body: JSON.stringify({ email: emailInput.value }),
35	          headers: { "Content-Type": "application/json" },
36	          method: "POST",
37	        });
38	        const data: SignUpResponse = await res.json();
39	
40	        if ("error" in data) {
41	          toast.error(data.error.message);
42	        } else {
43	          toast.success("Check your inbox — we sent you a confirmation.");
44	          form.reset();
45	        }
