export interface StreamRowConfig {
  delayMs: number;
  label: string;
}

/**
 * Three pieces of "work" with honest price tags. The delays are artificial;
 * the streaming is not — each row is a Server Component that genuinely
 * finishes on the server after this many milliseconds and streams into the
 * page whenever it's ready.
 */
export const STREAM_ROWS: readonly StreamRowConfig[] = [
  { delayMs: 400, label: "a quick database query" },
  { delayMs: 1100, label: "a third-party API with opinions" },
  { delayMs: 1900, label: "the legacy service nobody dares rewrite" },
];
=== press-count ===
import { cookies } from "next/headers";
import { COUNT_COOKIE, parseCount } from "./count-parser";

/**
 * A Server Component reading request data (your cookie), which is why the
 * page keeps it behind Suspense — it can't be baked into the shell, because
 * the shell is shared and your press count, tragically, is yours.
 */
export async function PressCount() {
  const jar = await cookies();
  const count = parseCount(jar.get(COUNT_COOKIE)?.value);

  return (
    <div className="flex flex-col gap-1">
      <p className="font-display font-medium text-4xl text-foreground tabular-nums tracking-tight sm:text-5xl">
        {count}
        <span className="ml-3 font-normal text-lg text-muted-foreground tracking-normal">
          {count === 1 ? "press" : "presses"}
        </span>
      </p>
      <p className="font-mono text-muted-foreground text-xs/5">
        read server-side from an httpOnly cookie — your JavaScript can&rsquo;t
        even see it
      </p>
    </div>
  );
}

export function PressCountFallback() {
  return (
    <div className="flex flex-col gap-1">
      <div className="flex h-10 items-center sm:h-12">
        <div className="h-8 w-24 rounded bg-foreground/10 motion-safe:animate-pulse" />
      </div>
      <p className="font-mono text-muted-foreground/60 text-xs/5">
        asking the server for your cookie…
      </p>
    </div>
  );
}
=== count-parser ===
export const COUNT_COOKIE = "playground-presses";
export const MAX_COUNT = 9999;

/**
 * A cookie is visitor-editable storage, so the value is parsed like it was
 * typed by a stranger — because it was. Anything that isn't a whole number
 * in range collapses to 0.
 */
const COUNT_PATTERN = /^\d{1,4}$/;

export function parseCount(raw: string | undefined): number {
  if (!(raw && COUNT_PATTERN.test(raw))) {
    return 0;
  }
  const parsed = Number.parseInt(raw, 10);
  return Math.min(parsed, MAX_COUNT);
}
=== bake-swatch ===
import { cn } from "@repo/design-system/lib/utils";

interface BakeSwatchProps {
  className?: string;
  /** The six-hex-char bake fingerprint — a CSS color by construction. */
  id: string;
}

/**
 * The color the fingerprint spells. A bake id is six hex characters, which
 * is to say a CSS color, so the swatch renders the literal value — nothing
 * derived, nothing truncated. It is deliberately unlabeled: the hex beside
 * it remains the information, this is the at-a-glance copy of it, and
 * working out that the chip *is* the hash is left as a pleasure.
 *
 * `aria-hidden` because the channel is redundant by design — screen readers
 * and colorblind visitors lose nothing but the glance.
 */
export function BakeSwatch({ className, id }: BakeSwatchProps) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        // The hairline border keeps a near-white bake visible on the panel
        // background; `em` sizing scales the chip with its context, from the
        // stamp headline down to a readout line.
        "inline-block size-[0.55em] rounded-[0.12em] border border-foreground/20",
        className
      )}
      style={{ backgroundColor: `#${id}` }}
    />
  );
}
