async () => {
  // A: reproduce with the page as shipped (no data attribute)
  const samples = [];
  window.scrollTo({ top: 2600, behavior: "instant" });
  await new Promise(r => setTimeout(r, 100));
  const startY = window.scrollY;
  document.querySelector('a[href="/lab/caching"]').click();
  const t0 = performance.now();
  for (let i = 0; i < 16; i++) {
    await new Promise(r => setTimeout(r, 60));
    samples.push({ t: Math.round(performance.now() - t0), y: Math.round(window.scrollY) });
  }
  return {
    computedScrollBehavior: getComputedStyle(document.documentElement).scrollBehavior,
    dataAttr: document.documentElement.dataset.scrollBehavior ?? null,
    startY,
    samples,
    endUrl: location.pathname,
  };
}

