async () => {
  // 1) Route navigation from a scrolled position: must open at the top instantly.
  window.scrollTo({ top: 2600, behavior: "instant" });
  await new Promise(r => setTimeout(r, 100));
  const navStartY = window.scrollY;
  document.querySelector('a[href="/lab/streaming"]').click();
  const navSamples = [];
  const t0 = performance.now();
  for (let i = 0; i < 6; i++) {
    await new Promise(r => setTimeout(r, 60));
    navSamples.push({ t: Math.round(performance.now() - t0), y: Math.round(window.scrollY) });
  }
  // 2) Back to the landing page, then an anchor click: must still glide.
  window.location.assign("/");
  return { navStartY, navSamples, landedOn: location.pathname };
}

