async () => {
  const $ = (sel) => document.querySelector(sel);
  const text = (el) => (el ? el.textContent.trim() : null);
  const out = {};

  // Locate the two cards by their pills.
  const pills = [...document.querySelectorAll("span")].filter(s => ["let count", "useState"].includes(s.textContent.trim()));
  out.pills = pills.map(p => p.textContent.trim());

  const varCard = pills[0]?.closest("div.flex.h-full");
  const stateCard = pills[1]?.closest("div.flex.h-full");
  const varButton = varCard?.querySelector("button");
  const stateButton = stateCard?.querySelector("button");
  const varNumber = varCard?.querySelector("p.font-display");
  const stateNumber = stateCard?.querySelector("p.ht-land, p.font-display");

  // 1) Var card: three clicks — number must stay 0, proof line must report 3.
  varButton.click(); varButton.click(); varButton.click();
  await new Promise(r => setTimeout(r, 120));
  out.varAfterClicks = { number: text(varNumber), proof: text(varCard.querySelector("p.min-h-5 span")) };

  // 2) State card, narrate off: two clicks — number must read 2.
  stateButton.click();
  await new Promise(r => setTimeout(r, 120));
  stateButton.click();
  await new Promise(r => setTimeout(r, 160));
  out.stateAfterClicks = { number: text(stateCard.querySelector("p.font-display")) };

  // 3) Narrate on, one more click: ask line must carry stale read, render line the new paint.
  const narrateSwitch = $("#state-narrate");
  narrateSwitch.click();
  await new Promise(r => setTimeout(r, 160));
  const stateCard2 = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "useState").closest("div.flex.h-full");
  stateCard2.querySelector("button").click();
  await new Promise(r => setTimeout(r, 250));
  const lines = [...stateCard2.querySelectorAll("div[aria-live] span")].map(s => s.textContent.trim());
  out.narrateLines = lines;

  // 4) Deck re-render: var proof must wipe, state number must survive, chip must reveal.
  const deckButton = [...document.querySelectorAll("button")].find(b => b.textContent.includes("Re-render the panel"));
  deckButton.click();
  await new Promise(r => setTimeout(r, 250));
  const varCard3 = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "let count").closest("div.flex.h-full");
  const stateCard3 = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "useState").closest("div.flex.h-full");
  out.afterRerender = {
    chipVisible: !![...document.querySelectorAll("span")].find(s => s.textContent.includes("let count → 0") && !s.closest(".invisible")),
    stateNumber: text(stateCard3.querySelector("p.font-display")),
    varBadge: text(varCard3.querySelector("span.ml-auto")),
    varProof: text(varCard3.querySelector("p.min-h-5 span")),
  };
  return out;
}

