1	/**
2	 * The syllabus registry — the single source of truth for the lab's shape.
3	 *
4	 * One entry per chapter, in accession order: shipped chapters first (the
5	 * array order is the reading order), then the one landing next Monday,
6	 * then the topics still to build. Everything that lists chapters derives
7	 * from here — the contents bar, the landing roadmap, prev/next, the
8	 * sitemap, per-page metadata — so shipping a chapter is one entry flip:
9	 * planned → next → shipped, belief and navLabel added, nothing else to
10	 * keep in sync.
11	 *
12	 * Beliefs are prose held in TS strings, so typographic marks are written
13	 * directly (voice.md §8): U+2019 apostrophes, U+201C/U+201D quotes.
14	 */
15	
16	interface ChapterCore {
17	  /** Accession number: assigned when a chapter enters the numbered queue, never reused. */
18	  readonly n: string;
19	  /** The chapter's URL segment under /lab — short, topical, stable forever. */
20	  readonly slug: string;
21	  /** The eyebrow identifier, lowercase: "caching & revalidation". */
22	  readonly topic: string;
23	}
24	
25	export interface ShippedChapter extends ChapterCore {
26	  /** The exhibit title — a belief the reader holds, in their words. */
27	  readonly belief: string;
28	  /** The short label the contents bar and prev/next links wear. */
29	  readonly navLabel: string;
30	  readonly status: "shipped";
31	}
32	
33	export interface NextChapter extends ChapterCore {
34	  readonly status: "next";
35	}
36	
37	export interface PlannedTopic {
38	  readonly status: "planned";
39	  readonly topic: string;
40	}
41	
42	export type SyllabusEntry = NextChapter | PlannedTopic | ShippedChapter;
43	
44	export const SYLLABUS: readonly SyllabusEntry[] = [
45	  {
46	    belief: "I’ll put “use client” on it, to be safe.",
47	    n: "01",
48	    navLabel: "The boundary",
49	    slug: "boundary",
50	    status: "shipped",
51	    topic: "server & client components",
52	  },
53	  {
54	    belief: "It’s either cached or it isn’t.",
55	    n: "02",
56	    navLabel: "The cache",
57	    slug: "caching",
58	    status: "shipped",
59	    topic: "caching & revalidation",
60	  },
61	  {
62	    belief: "I’ll fetch it all first, then render.",
63	    n: "03",
64	    navLabel: "The stream",
65	    slug: "streaming",
66	    status: "shipped",
67	    topic: "streaming & suspense",
68	  },
69	  {
70	    belief: "You need an API route for that.",
71	    n: "04",
72	    navLabel: "The mutation",
73	    slug: "server-actions",
74	    status: "shipped",
75	    topic: "server actions & cookies",
76	  },
77	  {
78	    belief: "I’ll need to design a card for every page.",
79	    n: "05",
80	    navLabel: "The image",
81	    slug: "og-images",
82	    status: "shipped",
83	    topic: "imageresponse & route handlers",
84	  },
85	  {
86	    belief: "I don’t need state for a simple counter.",
87	    n: "06",
88	    navLabel: "The state",
89	    slug: "state",
90	    status: "shipped",
91	    topic: "useState & re-renders",
92	  },
93	  {
94	    n: "07",
95	    slug: "navigation",
96	    status: "next",
97	    topic: "navigation & prefetching",
98	  },
99	  { status: "planned", topic: "dynamic routes & params" },
100	  { status: "planned", topic: "next/image, fonts & the asset pipeline" },
101	  { status: "planned", topic: "metadata, sitemaps & SEO" },
102	  { status: "planned", topic: "optimistic UI & useActionState" },
103	  { status: "planned", topic: "proxy, redirects & rewrites" },
104	  { status: "planned", topic: "error, not-found & recovery" },
105	  { status: "planned", topic: "parallel & intercepted routes" },
106	  { status: "planned", topic: "i18n & locale routing" },
107	  { status: "planned", topic: "view transitions" },
108	  { status: "planned", topic: "ISR & pages baked on demand" },
109	  { status: "planned", topic: "edge network & geolocation" },
110	  { status: "planned", topic: "feature flags & Edge Config" },
111	  { status: "planned", topic: "web vitals, measured live" },
112	  { status: "planned", topic: "preview deploys & instant rollback" },
113	  { status: "planned", topic: "cron, queues & background work" },
114	  { status: "planned", topic: "blob, key-value & Postgres" },
115	];
116	
117	export const SHIPPED: readonly ShippedChapter[] = SYLLABUS.filter(
118	  (entry): entry is ShippedChapter => entry.status === "shipped"
119	);
120	
121	export const NEXT_UP: NextChapter | undefined = SYLLABUS.find(
122	  (entry): entry is NextChapter => entry.status === "next"
123	);
124	
125	/** Topics not yet shipped, in syllabus order — the landing roadmap list. */
126	export const STILL_TO_BUILD: readonly string[] = SYLLABUS.flatMap((entry) =>
127	  entry.status === "shipped" ? [] : [entry.topic]
128	);
129	
130	const lastShipped = SHIPPED.at(-1);
131	if (!lastShipped) {
132	  throw new Error("syllabus: no shipped chapters — the lab has no contents");
133	}
134	
135	/** The newest shipped chapter — what /latest points at. */
136	export const LATEST: ShippedChapter = lastShipped;
137	
138	export function chapterBySlug(slug: string): ShippedChapter | undefined {
139	  return SHIPPED.find((chapter) => chapter.slug === slug);
140	}
141	
142	/** For call sites that hold a slug the registry must know — a typo is a build-time crash, not a silent gap. */
143	export function requireChapter(slug: string): ShippedChapter {
144	  const chapter = chapterBySlug(slug);
145	  if (!chapter) {
146	    throw new Error(`syllabus: no shipped chapter with slug "${slug}"`);
147	  }
148	  return chapter;
149	}
150	
151	/** Reading-order neighbors among shipped chapters only. */
152	export function prevNext(slug: string): {
153	  next?: ShippedChapter;
154	  prev?: ShippedChapter;
155	} {
156	  const index = SHIPPED.findIndex((chapter) => chapter.slug === slug);
157	  if (index === -1) {
158	    return {};
159	  }
160	  return { next: SHIPPED[index + 1], prev: SHIPPED[index - 1] };
161	}
