            <Suspense fallback={<IndexValueFallback />}>
              <IndexValue />
            </Suspense>
          </span>
        ) : null}
        <span className="col-start-2 mt-1 font-mono text-muted-foreground/80 text-xs">
          {chapter.topic}
        </span>
      </Link>
    </li>
  );
}

function NextRow({ entry }: { entry: NextChapter }) {
