          {entry.n}
        </span>
        <span className="font-medium text-foreground/60 text-xl tracking-tight">
          {entry.topic}
        </span>
        <span className="col-start-2 font-mono text-ht-cyan-700 text-xs sm:col-start-3 sm:justify-self-end dark:text-ht-cyan-300">
          lands Monday
        </span>
      </div>
    </li>
  );
}

