68	  const setActiveLine = (index: number | null) => {
69	    const lines = codeRef.current?.querySelectorAll(".line");
70	    if (!lines) {
71	      return;
72	    }
73	    lines.forEach((line, i) => {
74	      line.classList.toggle("ht-replay-active", i === index);
75	    });
76	  };
77	
78	  const schedule = (fn: () => void, ms: number) => {
79	    timeoutsRef.current.push(setTimeout(fn, ms));
80	  };
81	
82	  const writeNote = (text: string) => {
83	    if (noteRef.current) {
84	      noteRef.current.textContent = text;
85	    }
86	  };
87	
88	  const handleClick = () => {
89	    if (replayingRef.current) {
90	      return;
91	    }
92	    const next = count + 1;
93	    setCount(next);
94	    // Read *after* the setter on purpose: the closure's `count` still holds
95	    // the old value, because the new one does not exist until the next
96	    // render does. The replay's first annotation reports that read.
97	    const closureRead = count;
98	
99	    if (!narrate) {
100	      return;
101	    }
102	
103	    replayingRef.current = true;
104	    timeoutsRef.current = [];
105	    setFlipped(true);
106	    schedule(() => {
107	      setActiveLine(REPLAY_LINES.press);
108	      writeNote(stepPress(next, closureRead));
109	    }, FLIP_MS);
110	    schedule(() => {
111	      // Read at fire time: the render this step names has happened by now.
112	      setActiveLine(REPLAY_LINES.fn);
113	      writeNote(stepRender(renderTally));
114	    }, FLIP_MS + STEP_MS);
115	    schedule(
116	      () => {
117	        setActiveLine(REPLAY_LINES.useState);
118	        writeNote(stepReturns(next));
119	      },
120	      FLIP_MS + 2 * STEP_MS
121	    );
122	    schedule(
123	      () => {
124	        setActiveLine(REPLAY_LINES.paint);
125	        writeNote(stepPaints(next));
126	      },
127	      FLIP_MS + 3 * STEP_MS
128	    );
129	    schedule(
130	      () => {
131	        setFlipped(false);
132	        setActiveLine(null);
133	        writeNote("");
134	        // The paint happened while the card was turned; the wash marks its
135	        // reveal (re-triggered by hand — a keyed remount already played it
136	        // behind the card's back).
137	        if (numberRef.current) {
138	          numberRef.current.classList.remove("ht-land");
139	          void numberRef.current.offsetWidth;
140	          numberRef.current.classList.add("ht-land");
141	        }
142	        replayingRef.current = false;
143	      },
144	      FLIP_MS + 4 * STEP_MS
145	    );
146	  };
147	
148	  return (
149	    <StateCardShell
150	      facts={[
151	        "setCount stores the value where React keeps it",
152	        "then React calls the component again",
153	        "survives the panel re-rendering — that’s the job",
154	      ]}
155	      pill="useState"
156	      title={`state-card.tsx · pass ${panelPass}`}
157	      tone="state"
158	    >
159	      <div className="[perspective:1200px]">
160	        <div
161	          className={cn(
162	            "grid transition-transform duration-500 [transform-style:preserve-3d] motion-reduce:transition-none",
163	            flipped && "[transform:rotateY(180deg)]"
164	          )}
165	        >
166	          {/* Front: the counter. */}
167	          <div
168	            aria-hidden={flipped}
169	            className={cn(
170	              "flex flex-col justify-center gap-2 [backface-visibility:hidden] [grid-area:1/1]",
171	              flipped && "pointer-events-none"
172	            )}
173	          >
174	            <div className="flex items-center gap-4">
175	              <button
176	                className="inline-flex items-center justify-center rounded-full border border-transparent bg-primary px-4 py-[calc(0.5rem-1px)] font-medium text-base text-primary-foreground shadow-md hover:bg-primary/90"
177	                onClick={handleClick}
178	                type="button"
179	              >
180	                +1
181	              </button>
182	              <p
183	                className="ht-land font-display font-medium text-2xl text-foreground tabular-nums tracking-tight"
184	                key={count}
