191	                ref={badgeRef}
192	              />
193	            </div>
194	          </div>
195	          {/* Back: the source, walked line by line. Pointer events off while
196	              hidden — an invisible backface still sits over the button. */}
197	          <div
198	            aria-hidden={!flipped}
199	            className={cn(
