async () => {
  const out = {};
  const card = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "useState")?.closest("div.flex.h-full");
  const button = [...card.querySelectorAll("button")].find(b => b.textContent.trim() === "+1");
  const flipInner = card.querySelector("[class*='preserve-3d']");
  const note = card.querySelector("p[aria-live]");
  const isFlipped = () => flipInner.className.includes("rotateY(180deg)");
  const activeLineText = () => card.querySelector(".line.ht-replay-active")?.textContent?.trim() ?? null;

  // server-rendered code present on the back face before any click?
  out.codeLines = card.querySelectorAll(".line").length;
  out.shikiInBrowser = !!window.__shiki || Object.keys(window).some(k => k.toLowerCase().includes("shiki"));

  // 1) plain click (narrate off): instant, no flip
  button.click();
  await new Promise(r => setTimeout(r, 200));
  out.plainClick = { flipped: isFlipped(), number: card.querySelector("p.font-display").textContent.trim() };

  // 2) narrate on, click: sample the walk
  document.querySelector("#state-narrate").click();
  await new Promise(r => setTimeout(r, 150));
  button.click();
  const samples = [];
  const sampleAt = async (ms, label) => {
    await new Promise(r => setTimeout(r, ms));
    samples.push({ at: label, flipped: isFlipped(), line: activeLineText()?.slice(0, 46) ?? null, note: note.textContent.trim() });
  };
  await sampleAt(750, "step1");   // ~750ms
  await sampleAt(1050, "step2");  // ~1800ms
  await sampleAt(1050, "step3");  // ~2850ms
  await sampleAt(1050, "step4");  // ~3900ms
  await sampleAt(1200, "end");    // ~5100ms — flipped back
  out.samples = samples;
  out.finalNumber = card.querySelector("p.font-display").textContent.trim();
  out.badge = card.querySelector("span.ml-auto").textContent.trim();
  return out;
}

