async () => {
  const card = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "useState")?.closest("div.flex.h-full");
  const button = [...card.querySelectorAll("button")].find(b => b.textContent.trim() === "+1");
  const note = card.querySelector("p[aria-live]");
  const lines = [...card.querySelectorAll(".line")];
  const activeIndex = () => lines.findIndex(l => l.classList.contains("ht-replay-active"));

  document.querySelector("#state-narrate").click();
  await new Promise(r => setTimeout(r, 150));
  button.click();

  // Sample every 120ms for 6.5s; record each distinct active line + note transitions.
  const seen = [];
  const t0 = performance.now();
  while (performance.now() - t0 < 6500) {
    await new Promise(r => setTimeout(r, 120));
    const idx = activeIndex();
    const n = note.textContent.trim();
    const last = seen[seen.length - 1];
    if (!last || last.idx !== idx) seen.push({ idx, note: n, t: Math.round(performance.now() - t0) });
  }
  const flipInner = card.querySelector("[class*='preserve-3d']");
  return {
    lineOrder: seen.map(s => s.idx).filter(i => i >= 0),
    notesSeen: [...new Set(seen.map(s => s.note).filter(Boolean))],
    endedFlipped: flipInner.className.includes("rotateY(180deg)"),
    finalCount: card.querySelector(".ht-land")?.textContent?.trim(),
  };
}

