async () => {
  const card = [...document.querySelectorAll("span")].find(s => s.textContent.trim() === "useState")?.closest("div.flex.h-full");
  const button = [...card.querySelectorAll("button")].find(b => b.textContent.trim() === "+1");
  const items = () => [...card.querySelectorAll("li.ht-replay-note")].map(li => ({
    lit: li.classList.contains("ht-lit"),
    text: li.textContent.trim().slice(0, 44),
  }));

  document.querySelector("#state-narrate").click();
  await new Promise(r => setTimeout(r, 150));
  button.click();

  const out = {};
  await new Promise(r => setTimeout(r, 450));   // mid-flip, after populate
  out.atStart = items();
  await new Promise(r => setTimeout(r, 700));   // ~1150ms: first note lit, walk moving
  out.afterFirst = items();
  await new Promise(r => setTimeout(r, 1100));  // ~2250ms: second lit
  out.afterSecond = items();
  await new Promise(r => setTimeout(r, 1900));  // ~4150ms: third lit, all persist
  out.afterThird = items();
  await new Promise(r => setTimeout(r, 1600));  // past flip-back
  out.afterFlipBack = items();
  out.countNow = card.querySelector(".ht-land")?.textContent?.trim();
  return out;
}

