          <div
            aria-hidden={!flipped}
            className={cn(
              "[backface-visibility:hidden] [grid-area:1/1] [transform:rotateY(180deg)]",
              !flipped && "pointer-events-none"
            )}
          >
            <div ref={codeRef}>{replayCode}</div>
