                read at your own pace, not a ticker. */}
            <ol
              aria-live="polite"
              className="mt-2 grid gap-1 font-mono text-xs/5"
              ref={notesRef}
            >
              <li className="ht-replay-note min-h-5" />
              <li className="ht-replay-note min-h-5" />
              <li className="ht-replay-note min-h-5" />
            </ol>
            <p className="mt-1 font-mono text-[0.65rem] text-muted-foreground/70">
