() => {
  const inline = [...document.querySelectorAll(".prose code")].filter(c => !c.closest("pre"));
  const sample = inline.find(c => c.textContent.includes("fruits[2]"));
  const before = getComputedStyle(sample, "::before").content;
  const after = getComputedStyle(sample, "::after").content;
  const cs = getComputedStyle(sample);
  window.scrollTo(0, sample.getBoundingClientRect().top + window.scrollY - 200);
  return {
    inlineCount: inline.length,
    texts: inline.map(c => c.textContent),
    before, after,
    fontWeight: cs.fontWeight,
    fontFamily: cs.fontFamily.split(",")[0],
    hasBorder: cs.borderTopWidth,
    fencedUntouched: getComputedStyle(document.querySelector("pre.shiki code"), "::before").content,
  };
}

