import { cn } from "@repo/design-system/lib/utils";

type ColorVariant = "light" | "dark";

export function PlusGrid({
  className = "",
  children,
}: {
  className?: string;
  children: React.ReactNode;
}) {
  return <div className={className}>{children}</div>;
}

export function PlusGridRow({
  className = "",
  variant = "light",
  children,
}: {
  className?: string;
  variant?: ColorVariant;
  children: React.ReactNode;
}) {
  // "light"/"dark" name the section band behind the grid, not the theme —
  // so the light band's furniture still needs dark-theme values, or the
  // lines vanish the moment the theme flips.
  const borderColor =
    variant === "light"
      ? "border-black/5 dark:border-white/10"
      : "border-white/10";

  return (
    <div
      className={cn(
        className,
        "group/row relative isolate pt-[calc(0.5rem+1px)] last:pb-[calc(0.5rem+1px)]"
