async () => {
  const dark = [...document.querySelectorAll("button, label, [role=radio], input")].find(el => (el.textContent || el.getAttribute("aria-label") || "").toUpperCase().includes("DARK"));
  dark?.click();
  await new Promise(r => setTimeout(r, 400));
  const bar = document.querySelector("nav[aria-label='Contents']");
  return {
    darkApplied: document.documentElement.classList.contains("dark"),
    contentsLinks: bar ? [...bar.querySelectorAll("a")].map(a => a.getAttribute("href")) : null,
  };
}

