  const pill = document.querySelector("footer [role=radiogroup]");
  const p = pillItem.getBoundingClientRect();
  const c = pill.getBoundingClientRect();
  return {
    pillLeftInset: Math.round(c.left - p.left),
    pillRightInset: Math.round(p.right - c.right),
  };
}');
```

