        <SitemapLinks>
          <SitemapLink
            href="https://github.com/hasToggle/hasToggle.dev"
            target="_blank"
          >
            Source on GitHub
          </SitemapLink>
          <SitemapLink
            href="https://github.com/hasToggle/hasToggle.dev-checkpoints"
            target="_blank"
          >
            Prompts and checkpoints
