async () => {
  document.querySelector("footer").scrollIntoView({ block: "end" });
  await new Promise(r => setTimeout(r, 400));
  const rows = [...document.querySelectorAll("footer .group\\/row")];
  const bottomRow = rows[rows.length - 1];
  const items = [...bottomRow.querySelectorAll(".group\\/item")];
  return items.map(item => {
    const label = item.textContent.trim().slice(0, 18) || "(icons/controls)";
    const icons = [...item.querySelectorAll("svg[viewBox='0 0 15 15']")].map(svg => {
      const r = svg.getBoundingClientRect();
      const visible = getComputedStyle(svg).display !== "none";
      return { x: Math.round(r.x), y: Math.round(r.y), visible };
    });
    const box = item.getBoundingClientRect();
    return { label, itemY: Math.round(box.y), itemH: Math.round(box.height), icons };
  });
}

