async () => {
  document.querySelector("footer").scrollIntoView({ block: "end" });
  await new Promise(r => setTimeout(r, 400));
  const rows = [...document.querySelectorAll("footer .group\\/row")];
  const bottomRow = rows[rows.length - 1];
  const ys = [...bottomRow.querySelectorAll("svg[viewBox='0 0 15 15']")]
    .filter(svg => getComputedStyle(svg).display !== "none")
    .map(svg => Math.round(svg.getBoundingClientRect().y));
  const navLogoIcons = document.querySelectorAll("header a[title=Home] ~ svg, header .group\\/item svg[viewBox='0 0 15 15']").length;
  const footerTopRowIcons = [...rows[0].querySelectorAll("svg[viewBox='0 0 15 15']")].filter(s => getComputedStyle(s).display !== "none").length;
  return {
    bottomRowIconYs: [...new Set(ys)].sort(),
    headerHasLogoIcons: navLogoIcons,
    footerTopRowVisibleIcons: footerTopRowIcons,
  };
}

